import{d as l,C as t,o as p,c as h,E as a,a3 as i}from"./chunks/framework.D4-ViStF.js";const b=JSON.parse('{"title":"革卦","description":"第四十九卦·泽火革——水火相息，二女同居，其志不相得。革是改变旧有，顺乎天而应乎人；虎变定调，豹变落实，收手守成。","frontmatter":{"title":"革卦","description":"第四十九卦·泽火革——水火相息，二女同居，其志不相得。革是改变旧有，顺乎天而应乎人；虎变定调，豹变落实，收手守成。","category":"hexagram","aliases":["革","泽火革","革卦"],"source":["《周易》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/hexagrams/49-zehuoge.md","filePath":"yijing/hexagrams/49-zehuoge.md","lastUpdated":1789714390000}'),d={name:"yijing/hexagrams/49-zehuoge.md"},x=l({...d,setup(m){const e=[{id:"fu",term:"孚",pinyin:"fú",meaning:"诚信、信实。此处指人心真正的归附与信任。",context:"卦辞「己日乃孚」；九三「有孚」；九四「有孚改命」；九五「未占有孚」——全卦是一条「挣孚 → 验孚 → 孚自明」的递进链。"},{id:"jiri",term:"己日",pinyin:"jǐ rì",meaning:"天干第六位，象征变革过半的转折点。",context:"变革不是宣告即成的，要等到关键节点过去，人心才会真正归附——故曰「己日乃孚」。"},{id:"gong",term:"巩",pinyin:"gǒng",meaning:"巩固、用皮革捆束。",context:"「巩用黄牛之革」：主动用比自己更坚固的外物捆住自己，防止被躁动环境带偏而妄动。"},{id:"huangniu",term:"黄牛之革",pinyin:"huáng niú zhī gé",meaning:"黄牛皮制成的坚韧皮绳，喻坚固可靠的约束。",context:"遁卦六二「执之用黄牛之革，莫之胜说」同一意象——用于退避守静与变革守动两种处境，内核相通：对抗外界拉扯或内心躁动。"},{id:"gesan",term:"革言三就",pinyin:"gé yán sān jiù",meaning:"「三」虚指反复多次；变革的言论反复申说、经得起核验，直至确认站得住。",context:"九三当位却仍「贞厉」，凶险不在位不正，而在临界与孤立——须靠反复核验挣得人心之孚。"},{id:"gaiming",term:"改命",pinyin:"gǎi mìng",meaning:"宣告并完成新的秩序、新的命数。",context:"「革」是动词、是过程；「改命」是结果、是完成态。九四得吉，正因「改命」这个动作本身宣告了旧规矩已失效。"},{id:"hubian",term:"虎变",pinyin:"hǔ biàn",meaning:"老虎秋天换毛后花纹格外清晰鲜亮。",context:"象曰「其文炳也」——炳为光亮鲜明、远观即辨。喻大人变革是宏观的、一望便知、定基调的巨变，重点在「文」（秩序与可见之美），不在凶猛肃杀。"},{id:"baobian",term:"豹变",pinyin:"bào biàn",meaning:"豹纹茂密细腻，需近观细品。",context:"象曰「其文蔚也」——与虎变相对：虎变宏观定调，豹变精细落实。"},{id:"gemian",term:"革面",pinyin:"gé miàn",meaning:"只改脸面、未真心认同，是看清风向后的功利顺从（「顺以从君也」）。",context:"任何变革收尾阶段必然存在的常态，执政者需接受而非强求人人彻底「豹变」。"},{id:"wenbing",term:"其文炳也",pinyin:"qí wén bǐng yě",meaning:"炳，光亮鲜明。谓九五之变，远观即辨，鲜明到一望便知。",context:"回扣彖传「文明以说」：革的最终追求，是建立一套让天下人一看就明白、一看就信服的清晰新秩序。"},{id:"wenwei",term:"其文蔚也",pinyin:"qí wén wèi yě",meaning:"蔚，茂密。谓上六之变，纹理由粗到细，需近观方能体察。",context:"与「其文炳也」相对，见虎变与豹变的层次分野。"},{id:"zhili",term:"治历明时",pinyin:"zhì lì míng shí",meaning:"修治历法、明定时节。",context:"象传「泽中有火，革。君子以治历明时」——变革的第一件实操不是庆功，而是重新校准天下运行的时间标准：变革的合法性落地。"},{id:"shuntian",term:"顺乎天而应乎人",pinyin:"shùn hū tiān ér yìng hū rén",meaning:"顺天是前置门槛（时机、大势是否成熟），应人是验证条件（民心是否真正归附）。",context:"二者不是平行的加分项，而是先后相扣的因果链：缺顺天则崩于发动（陈胜吴广、太平天国），缺应人则崩于维系（王莽新朝）。"},{id:"tangwu",term:"汤武革命",pinyin:"tāng wǔ gé mìng",meaning:"商汤灭夏桀、周武王灭商纣。中国历史上「革命」一词最早、最正面的原型。",context:"孟子称「汤武革命，顺乎天而应乎人」，为本卦所引。"},{id:"xiangxi",term:"水火相息",pinyin:"shuǐ huǒ xiāng xī",meaning:"水与火相互制约、彼此消解。",context:"彖传首句释卦象：泽中有火，两种相反之力同处，张力必然导致改变。"},{id:"ernv",term:"二女同居",pinyin:"èr nǚ tóng jū",meaning:"兑为少女、离为中女，二女同处一室。",context:"「其志不相得」——两种性质截然相反的力量被迫共处，故曰革。"},{id:"zheng",term:"征",pinyin:"zhēng",meaning:"前往、强行推进。",context:"六二「征吉」是趁时出手；九三「征凶」是临界冒进；上六「征凶」是变革已到终点仍继续折腾。同一个「征」字，三种时机三种结果。"},{id:"zhen",term:"贞",pinyin:"zhēn",meaning:"守正、坚守本位。",context:"九三「贞厉」——当位守正仍有危厉，因处境临界；上六「居贞吉」——变革收尾，安定守成才是吉。"}],o=[{position:"初九",type:"yang",text:"巩用黄牛之革。",xiang:"巩用黄牛，不可以有为也。",textModern:"变革之初，躁动的氛围已经形成，但此时不可有所作为。自知意志力可能守不住，便主动用比自己更坚固的外物（黄牛皮绳）捆住自己，防止被环境带偏而妄动。",xiangModern:"用黄牛之革自我捆束，是说此刻不可以有所作为。"},{position:"六二",type:"yin",text:"己日乃革之，征吉，无咎。",xiang:"己日革之，行有嘉也。",textModern:"等到变革过半的关键节点才出手，前往则吉、无过咎。三重资格叠加，才有资格「革」：得中且正、有离明之智（天生能准确判断「己日」）、又与九五相应而非孤军突进。",xiangModern:"在己日发动变革，行动必有嘉美之效。"},{position:"九三",type:"yang",text:"征凶，贞厉。革言三就，有孚。",xiang:"革言三就，又何之矣。",textModern:"前往则凶，守正也危厉。当位却仍险——内卦离火积蓄到极限、即将突破的临界点，且与九四「比」而非「应」，两阳相邻、彼此推不动扶不上。只有当变革之说反复申说核验、确认站得住，才真正挣得人心之「孚」。",xiangModern:"变革之言已经反复核验，还要往哪里去呢。"},{position:"九四",type:"yang",text:"悔亡，有孚改命，吉。",xiang:"改命之吉，信志也。",textModern:"悔恨消失，凭已挣得的信任宣告「改命」，吉。九四本身不当位，却是全卦少数干脆说「吉」的位置——因为「改命」这个动作本身，重新定义了旧秩序里「位正才吉」的判断标准。它的吉不是靠符合旧规矩挣来的，而是旧规矩已被宣告失效。",xiangModern:"改命之所以吉，是因为心志得到了信从。"},{position:"九五",type:"yang",text:"大人虎变，未占有孚。",xiang:"大人虎变，其文炳也。",textModern:"如虎秋后换毛，花纹格外鲜明——得中且正的君位所完成的变革，是宏观的、一望便知的定调巨变。其要在「文」（秩序与可见之美），不在凶猛。这份人心之信已强到连占卦确认都是多余：比任何「吉」字都更高的评价。",xiangModern:"大人虎变，其文采光明显著。"},{position:"上六",type:"yin",text:"君子豹变，小人革面。征凶，居贞吉。",xiang:"君子豹变，其文蔚也。小人革面，顺以从君也。",textModern:"君子如豹，纹理由粗到细、茂密可观，把变革精细落实到每一个细节角落；小人只改了脸面，是看清风向后的功利顺从——这不是变革的失败，而是收尾阶段必然存在的常态，需接受而非强求。此时继续折腾（征）则凶，安定守成（居贞）才是吉。",xiangModern:"君子豹变，其文采茂密；小人只革其面，是顺从在上者而已。"}];return(u,n)=>{const r=t("DaoHexagramViewer"),s=t("DaoHexagramYaoCards"),g=t("DaoKeywordCards");return p(),h("div",null,[a(r,{name:"革",fullName:"泽火革",upper:"☱",lower:"☲",guaCi:"革，己日乃孚，元亨利贞，悔亡。",pinyin:["gé"],element:"水",direction:"北",insight:"泽中有火，水火相激。变革不是宣告即成，要等关键节点过去人心才归附；顺天是启动条件，应人是完成条件，二者先后相扣。虎变定调，豹变落实，到该收手时必须收手。",guaSlug:"49zehuoge",lines:o}),n[0]||(n[0]=i("",16)),a(s,{element:"水",guaSlug:"49zehuoge",glossary:e,items:o}),n[1]||(n[1]=i("",36)),a(g,{title:"字词释义",items:[{term:"孚",pinyin:["fú"],meaning:"诚信、信实。此处指人心真正的归附与信任——全卦从「己日乃孚」到「未占有孚」，是一条信任逐级建立的链条。"},{term:"己日",pinyin:["jǐ","rì"],meaning:"天干第六位，象征变革过半的转折点。变革不是宣告即成的，要等到关键节点过去，人心才会真正归附。"},{term:"巩",pinyin:["gǒng"],meaning:"巩固、用皮革捆束。「巩用黄牛之革」是主动用比自己更坚固的外物约束自己。"},{term:"黄牛之革",pinyin:["huáng","niú","zhī","gé"],meaning:"黄牛皮制成的坚韧皮绳。遁卦六二同一意象，用于守静与守动两种处境，内核都是对抗拉扯或躁动。"},{term:"革言三就",pinyin:["gé","yán","sān","jiù"],meaning:"变革之说反复申说、经得起核验直至站得住。「三」是虚指多次，非实指三次。"},{term:"改命",pinyin:["gǎi","mìng"],meaning:"宣告并完成新的秩序。与「革」（过程）相对，是结果、完成态。"},{term:"虎变",pinyin:["hǔ","biàn"],meaning:"老虎秋后换毛，花纹格外清晰鲜亮。象曰「其文炳也」——宏观定调、一望便知。"},{term:"豹变",pinyin:["bào","biàn"],meaning:"豹纹茂密细腻，需近观细品。象曰「其文蔚也」——精细落实到每个角落。"},{term:"革面",pinyin:["gé","miàn"],meaning:"只改脸面而未真心认同，是看清风向后的功利顺从。收尾期的常态，非变革失败。"},{term:"治历明时",pinyin:["zhì","lì","míng","shí"],meaning:"修治历法、明定时节。象传所示：变革的第一件实操是重新校准天下运行的时间标准。"},{term:"水火相息",pinyin:["shuǐ","huǒ","xiāng","xī"],meaning:"水与火相互制约、彼此消解。彖传首句释卦象。"},{term:"二女同居",pinyin:["èr","nǚ","tóng","jū"],meaning:"兑为少女、离为中女，二女同处一室而志不相得——两种相反之力被迫共处，故成变革之势。"},{term:"顺乎天而应乎人",pinyin:["shùn","hū","tiān","ér","yìng","hū","rén"],meaning:"顺天是前置门槛，应人是验证条件。先后相扣的因果链：缺顺天崩于发动，缺应人崩于维系。"},{term:"汤武革命",pinyin:["tāng","wǔ","gé","mìng"],meaning:"商汤灭夏桀、周武王灭商纣，是「革命」一词最早、最正面的历史原型。"},{term:"悔",pinyin:["huǐ"],meaning:"困厄、悔恨。卦辞「悔亡」——处理得当，最初的悔恨疑虑都会消失。"},{term:"咎",pinyin:["jiù"],meaning:"灾祸、罪过。六二「无咎」谓如此行动没有过咎。"},{term:"厉",pinyin:["lì"],meaning:"危险、戒惧。九三「贞厉」——当位守正仍有危厉。"}]}),n[2]||(n[2]=i("",37))])}}});export{b as __pageData,x as default};
